<?php require 'config.php';if(empty($_SESSION['user_id']))go('login.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$t=trim($_POST['title']??'');$d=trim($_POST['department']??'');$cat=trim($_POST['category']??'');$desc=trim($_POST['description']??'');if(!$t||!$d||!$cat||!$desc)$err='Please complete all fields.';else{$code='NML'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare('INSERT INTO complaints(complaint_code,user_id,title,department,category,description) VALUES(?,?,?,?,?,?)');$s->execute([$code,$_SESSION['user_id'],$t,$d,$cat,$desc]);msg('Complaint registered. Your ID: '.$code);go('my_complaints.php');}}$title='Register Complaint';require 'partials/top.php';?><section class="glass panel formpanel"><h3>Raise a Complaint</h3><p>Provide clear details so the team can review your concern.</p><?=$err?'<div class="alert">'.e($err).'</div>':''?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Complaint title *</label><input name="title" required maxlength="180"><label>Department *</label><input name="department" required><label>Category *</label><select name="category" required><option value="">Choose category</option><option>IT / Infrastructure</option><option>Workplace Safety</option><option>Facilities / Maintenance</option><option>Cleanliness</option><option>HR / Administration</option><option>Other</option></select><label>Description *</label><textarea name="description" rows="5" required></textarea><button>Submit Complaint →</button></form></section><?php require 'partials/bottom.php';?>